// Multiply, a built-in occupant of the `combiner` slot (dd_colouring §3.5): rgb·b in linear space, so the base keeps its
// own L structure (the combiner for monotone-L LUTs, render contract Part 4). The CPU mirror is
// `crates/render/src/colour/combine.rs`.
// @name Multiply
// @group Combiner
// @about The colour times half the brightness plus a half, in linear RGB.
// @maps colour · brightness
// @glyph dropdown
fn combine(rgb: vec3<f32>, b: f32) -> vec3<f32> { return rgb * (0.5 + 0.5 * b); }

// The built-in source of `E_0`: the field in `.x` (render_gui_spec Part II §3.1).
// @name ctx.E_0
// @group Source
// @about The read-side field E_0, in the field's x.
// @maps ctx.E_0
// @glyph dropdown
fn source(ctx: Ctx) -> Field { return Field(f32(ctx.sample.E_0), 0.0, 0.0, 0.0); }

// The built-in source of `state`: the field in `.x` (render_gui_spec Part II §3.1).
// @name ctx.state
// @group Source
// @about The read-side field state, in the field's x.
// @maps ctx.state
// @glyph dropdown
fn source(ctx: Ctx) -> Field { return Field(f32(ctx.sample.state), 0.0, 0.0, 0.0); }

// The margin, a built-in occupant of the `colour` slot (render_gui_spec Part II §5, §3.1, §15 item 6; R-813;
// TASK-M7-12): a multi-source mapping. It declares two field inputs, `top1` and `top2`, so its node has two `field`
// in-ports, each taking one wire, never two wires on one port (§6), and shows the margin `top1 − top2`, each input's
// value its field's `.x`. A source keeps no input (§3.1): the two fields reach the margin as two wires from two
// sources, or from one (§5: fan-out is free).
//
// **The map is R-962's** (colour_composition §1.2, "Default ramps by field role"): the margin is drawn on the
// greyscale ramp, `ramp_grey`, OKLab L equal to `top1 − top2` clamped to [0, 1], white where `top1` is far above
// `top2`, so a margin below 0 draws the ramp's black (a swapped pair of wires is all black) and one above 1 its white.
// The last line below is that map; the two inputs and the guards before it are the node's.
//
// It is a presentation view and draws no hatch (R-467), so it guards itself, as the outcome state and a field ramp
// do (render contract "Presentation layer"; render_gui_spec §G1, §13 "Validity-first"): a pixel the chart classifies
// as not a system, `ctx.validity.forbidden`, and a `decode_failed` sample draw the canvas background, blank, never a
// place on the map (R-467, R-470, R-511); a `sim_failed` sample and a reserved `state` code draw the presentation
// views' invalid colour, `PRESENT_INVALID`, #141418, whatever the inputs hold; and a margin that is not finite has
// no value: it is noted for the debug view (`note_non_finite()`) and draws #141418 too. Not finite is an input that
// is not finite or a difference that is not (two finite inputs may overflow), each by its bits: the inputs are
// tested themselves because a backend's fast-math may fold `x − x` to 0 where one source feeds both ports, and ∞ − ∞
// must not draw the map's zero on one backend and #141418 on another.
// @name Margin
// @group Colour
// @about The margin top1 − top2 on the grey ramp, white where top1 is far above top2.
// @maps top1 − top2 [lin, 0 to 1]
// @glyph name
// @input top1
// @input top2
// Whether `x` is ±∞ or a NaN, by its bits: every exponent bit set.
fn margin_non_finite(x: f32) -> bool {
    return (bitcast<u32>(x) & 0x7f800000u) == 0x7f800000u;
}

fn colour(ctx: Ctx) -> vec3<f32> {
    if (ctx.validity.forbidden || ctx.sample.state == STATE_DECODE_FAILED) {
        return canvas_background();
    }
    if (ctx.sample.state == STATE_SIM_FAILED || ctx.sample.state > STATE_DECODE_FAILED) {
        return PRESENT_INVALID;
    }
    let top1 = ctx.inputs[0].x;
    let top2 = ctx.inputs[1].x;
    let margin = top1 - top2;
    if (margin_non_finite(top1) || margin_non_finite(top2) || margin_non_finite(margin)) {
        note_non_finite();
        return PRESENT_INVALID;
    }
    return ramp_grey(margin); // the map R-962 rules
}

// A brightness of its field.
// @uniform gain: f32 = 0.5 [0.0, 1.0]
fn brightness(ctx: Ctx) -> f32 { return clamp(ctx.inputs[0].x * uniforms.gain, 0.0, 1.0); }

// The Tier-1 boundary overlay (render_gui_spec §12.1; REQ-RENDER-024; TASK-M1-13): an ordinary post node, drawn from
// the address alone, `ctx.quad.uv` for quad boundaries and `ctx.tile.uv` for tile boundaries, with no buffer and no
// pass of its own. `edge_line` gives the line's coverage at a pixel from its distance, in pixels, to the nearest edge
// of its cell, so a line is the same width in pixels at any quad size, depth and zoom, and antialiased.
//
// `width` and `opacity` style the quad boundaries, `tile_width` and `tile_opacity` the tile boundaries, `colour`
// (linear RGB) both; `level` picks what is drawn: 0 the quad boundaries, 1 the tile boundaries, 2 both, composited by
// the larger coverage, so an edge both cells share is drawn once. A width is the line's full width across the edge, in
// pixels, at half coverage. The leaf outlines are the quad boundaries of the quads drawn (debug_tooling_plan §F).
// @name Boundary lines
// @group Post
// @about Lines along the quad and tile boundaries, the same width in pixels at any zoom.
// @maps the quad and tile boundaries
// @glyph name
// @uniform width: f32 = 2.0 [0.25, 16.0]
// @control width slider "Width" in "Quad lines" order 1
// @uniform opacity: f32 = 1.0 [0.0, 1.0]
// @control opacity slider "Opacity" in "Quad lines" order 2
// @uniform tile_width: f32 = 1.0 [0.25, 16.0]
// @control tile_width slider "Width" in "Tile lines" order 3
// @uniform tile_opacity: f32 = 0.5 [0.0, 1.0]
// @control tile_opacity slider "Opacity" in "Tile lines" order 4
// @uniform colour: vec3<f32> = (1.0, 1.0, 1.0)
// @control colour colour "Line colour" order 5
// @uniform level: u32 = 0 [0, 2]
// @control level choice("quads", "tiles", "both") "Draw" order 0

// One pixel's size in the cell coordinate `uv`, per axis: `fwidth(uv)`, each derivative taken modulo the cell, so that
// a 2 × 2 pixel block straddling a cell edge, where `uv` jumps from near 1 to near 0, still reads the step within a
// cell, `1 / (cell size in px)`, not the jump (TASK-M1-13; applied per R-369). §12.1's `fwidth(d)` of the edge distance
// reads 0 there, the distance being equal on both sides of the edge, and at a cell's corner, where the nearer axis
// changes; this reads the pixel's size wherever the cell is at least 2 px wide.
fn cell_fwidth(uv: vec2<f32>) -> vec2<f32> {
    let dx = dpdx(uv);
    let dy = dpdy(uv);
    return abs(dx - round(dx)) + abs(dy - round(dy));
}

// render_gui_spec §12.1's `edge_line`: the distance to the nearest edge of the cell, cell-local, converted to pixels by
// the pixel's size in `uv`, then `1 − smoothstep(0, width_px, d)`: constant pixel width, antialiased.
fn edge_line(uv: vec2<f32>, width_px: f32) -> f32 {
    let e = min(uv, vec2<f32>(1.0) - uv);
    let px = e / cell_fwidth(uv);
    let d = min(px.x, px.y);
    return 1.0 - smoothstep(0.0, width_px, d);
}

fn post(ctx: Ctx, rgb: vec3<f32>) -> vec3<f32> {
    // Both lines are evaluated whatever `level` is: the derivatives need uniform control flow.
    let quad = uniforms.opacity * edge_line(ctx.quad.uv, uniforms.width);
    let tile = uniforms.tile_opacity * edge_line(ctx.tile.uv, uniforms.tile_width);
    // A lane the raster did not place (`shade_sample`) holds the absence NaN: no line there.
    let q = select(quad, 0.0, uniforms.level == 1u || is_absent_nan(ctx.quad.uv.x));
    let t = select(tile, 0.0, uniforms.level == 0u || is_absent_nan(ctx.tile.uv.x));
    return mix(rgb, uniforms.colour, max(q, t));
}
